!solve(input){ 
    let { stack, action, value, history } = input;
    if (action === "push") {
        history.push([...stack, value]);
        return { stack: [...stack, value], history };
    } else if (action === "pop") {
        if (stack.length > 0) {
            history.push([...stack]);
            return { stack: stack.slice(0, -1), history };
        } else {
            return { stack, history };
        }
    } else if (action === "rollback") {
        if (history.length > 0) {
            return { stack: history.pop(), history };
        } else {
            return { stack, history };
        }
    }
}

!solve(input){ 
  let { stack, action, value, history } = input;
  let newStack = [...stack];
  let newHistory = [...history];

  if (action === "push") {
    newStack.push(value);
    newHistory.push([...newStack]);
  } else if (action === "pop") {
    if (newStack.length > 0) {
      newStack.pop();
      newHistory.push([...newStack]);
    }
  } else if (action === "rollback") {
    if (newHistory.length > 1) {
      newStack = newHistory[newHistory.length - 2];
      newHistory = newHistory.slice(0, newHistory.length - 1);
    }
  }

  return { stack: newStack, history: newHistory };
}

