            removed.push(key);
        }
    }

    for (let key in input.newObj) {
        if (!(key in input.oldObj)) {
            added.push(key);
        }
    }

    for (let key in input.oldObj) {
        if (key in input.newObj) {
            if (input.oldObj[key] !== input.newObj[key]) {
                updated.push(key);
            }
        }
    }

    added.sort();
    removed.sort();
    updated.sort();

    return { added: added, removed: removed, updated: updated };
}

